import{_ as e,o as t,c as s,ag as n}from"./chunks/framework.DO6ntPSX.js";const u=JSON.parse('{"title":"安全设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/safety.md","filePath":"zh/features/safety.md","lastUpdated":1785115728000}'),d={name:"zh/features/safety.md"};function r(o,a,l,i,c,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="安全设计" tabindex="-1">安全设计 <a class="header-anchor" href="#安全设计" aria-label="Permalink to &quot;安全设计&quot;">​</a></h1><p>Mneme 将策略集中在 <code>src/security.py</code> 中，CLI、TUI、查询拆解和 Graph RAG 共享同一套检查。</p><h2 id="端点安全" tabindex="-1">端点安全 <a class="header-anchor" href="#端点安全" aria-label="Permalink to &quot;端点安全&quot;">​</a></h2><ul><li><strong>默认 HTTPS</strong>：远程端点要求 HTTPS；回环地址（<code>localhost</code>、<code>127.0.0.1</code>、<code>::1</code>）允许 HTTP</li><li><strong>显式覆盖</strong>：非本地 HTTP 需要显式的 <code>MNEME_ALLOW_INSECURE_HTTP=1</code> 覆盖</li><li><strong>客户端刷新</strong>：Graph RAG 缓存绑定当前 API key 和 base URL，端点变更立即生效</li></ul><h2 id="文档安全措施" tabindex="-1">文档安全措施 <a class="header-anchor" href="#文档安全措施" aria-label="Permalink to &quot;文档安全措施&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制</th><th>默认值</th><th>目的</th></tr></thead><tbody><tr><td>文档大小限制</td><td>50 MiB（<code>52428800</code>）</td><td>防止意外索引巨大文件</td></tr><tr><td>PDF 页数限制</td><td>2000 页</td><td>限制提取时间和内存</td></tr><tr><td>文档根目录</td><td>可选（<code>MNEME_DOCUMENT_ROOT</code>）</td><td>限制索引到特定目录树</td></tr><tr><td><code>.env</code> 拒绝</td><td>始终</td><td>防止 API Key 被索引</td></tr></tbody></table><h2 id="上下文边界" tabindex="-1">上下文边界 <a class="header-anchor" href="#上下文边界" aria-label="Permalink to &quot;上下文边界&quot;">​</a></h2><p>检索到的文本被放入显式的不可信文档边界中：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Source: report.pdf] [Citation: S1]</span></span>
<span class="line"><span>&lt;untrusted_document chunk_id=&quot;source-a_chunk_3&quot;&gt;</span></span>
<span class="line"><span>检索到的文本 ...</span></span>
<span class="line"><span>&lt;/untrusted_document&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>模型被指示将此部分视为数据而非指令。即使文档中包含&quot;忽略前面的指令&quot;等文字，它也应留在不可信文档区域内。</p><h3 id="上下文截断安全" tabindex="-1">上下文截断安全 <a class="header-anchor" href="#上下文截断安全" aria-label="Permalink to &quot;上下文截断安全&quot;">​</a></h3><p>上下文长度受限制（默认：60,000 字符）。Mneme 只截断 <code>document_text</code>，保留完整的来源标记、引用和开闭边界。当完整安全框架容纳不下时跳过该 chunk。安全边界不应该是预算紧张时第一个被牺牲的东西。</p><h2 id="缓存安全" tabindex="-1">缓存安全 <a class="header-anchor" href="#缓存安全" aria-label="Permalink to &quot;缓存安全&quot;">​</a></h2><ul><li>Graph RAG 缓存使用 <strong>Schema 验证的原子 JSON</strong>，而不是加载 pickle</li><li>缓存必须匹配当前索引指纹和 manifest 版本</li><li>旧版 <code>.pkl</code> 文件在不加载的情况下失效</li></ul><h2 id="数据披露" tabindex="-1">数据披露 <a class="header-anchor" href="#数据披露" aria-label="Permalink to &quot;数据披露&quot;">​</a></h2><p>索引和检索在本地运行，但检索到的文档片段会在查询拆解、Graph RAG 实体提取和回答生成时发送到配置的端点。引导向导会明确披露这一点。</p>`,16)])])}const b=e(d,[["render",r]]);export{u as __pageData,b as default};
